//! Authored source bytes only: old and native compute all semantic outcomes independently.
pub const CASES:&[&str]=&["basic","calls","aliases","recursive","dispatch","schema","schema_order","settings","macro","noncode","exempt","summary"];
pub fn files(case:&str)->Vec<(&'static str,Vec<u8>)>{assert!(CASES.contains(&case));let types="#define SCHEMA(T,V,K)\n#define TRACKED_SCHEMA(T,V,K)\n/datum/msg\n/datum/msg/good\n/datum/holder\n    var/saved\n    var/scalar\n    var/path\n    proc/entity()\n        return new /datum/holder\n    proc/number()\n        return 7\n";
 let source=match case{
 "calls"=>"/datum/holder/proc/check()\n    saved = entity()\n    scalar = number()\n",
 "aliases"=>"/datum/holder/proc/check()\n    var/temp = entity()\n    var/copy = temp\n    saved = copy\n    var/value = number()\n    scalar = value\n",
 "recursive"=>"/datum/holder/proc/left()\n    return right()\n/datum/holder/proc/right()\n    if(world.time)\n        return left()\n    return 7\n/datum/holder/proc/check(datum/holder/P)\n    scalar = left()\n    saved = P\n",
 "dispatch"=>"/datum/holder/sub/number()\n    return new /datum\n/datum/holder/proc/check()\n    saved = number()\n",
 "schema"=>"SCHEMA(/datum/holder,path,schema_msg())\n/datum/holder/proc/check(datum/holder/P)\n    path = /datum/holder\n    saved = P\n",
 "schema_order"=>"/datum/holder/proc/check(datum/holder/P)\n    path = /datum/holder\n    saved = P\n",
 "settings"=>"/datum/holder/proc/check(datum/holder/P)\n    set desc = (saved = P)\n    saved = P\n",
 "macro"=>"#define SAVE_TYPED(V) saved = V\n/datum/holder/proc/check(datum/holder/P)\n    SAVE_TYPED(P)\n    saved = P\n",
 "noncode"=>"// assignments are in the actually compiled map body\n",
 "summary"=>"/datum/holder/proc/check(datum/holder/P)\n    saved = P\n    saved = P\n    saved = P\n    saved = P\n    saved = P\n    saved = P\n    saved = P\n    saved = P\n    saved = P\n    saved = P\n",
 _=>"/datum/holder/proc/check(datum/holder/P)\n    saved = P\n"};let config=if case=="exempt"{"[lint.untyped]\nexempt_prefixes=['code/']\n"}else{""};let mut out=vec![("deepquarry.dme",b"#include \"code/types.dm\"\n#include \"code/z_schema.dm\"\n#include \"code/a_schema.dm\"\n#include \"code/main.dm\"\n".to_vec()),("code/types.dm",types.as_bytes().to_vec()),("code/z_schema.dm",if case=="schema_order"{b"SCHEMA(/datum/holder,path,schema_any())\nTRACKED_SCHEMA(/datum/holder,path,schema_msg())\n".to_vec()}else{b"// no schema\n".to_vec()}),("code/a_schema.dm",if case=="schema_order"{b"SCHEMA(/datum/holder,path,schema_path(/datum/holder))\n".to_vec()}else{b"// no schema\n".to_vec()}),("code/main.dm",source.as_bytes().to_vec()),("tools/ci/lint_scopes.toml",config.as_bytes().to_vec())];if case=="noncode"{out[0].1.extend_from_slice(b"#include \"maps/untyped.dm\"\n");out.push(("maps/untyped.dm",b"/datum/holder/proc/map_save(datum/holder/P)\n    saved = P\n/datum/map_declaration\n    var/map_saved\n    proc/check(datum/holder/P)\n        map_saved = P\n".to_vec()));}out}
